def icon_bytes() -> bytes:
    return base64.b64decode(APP_ICON_ICO_BASE64)


def icon_path(folder: Path | None = None) -> Path | None:
    """ICO を書き出したパス（既にあれば中身を確かめて使う）。書けないときは None（アイコン無しで続ける）。"""
    data = icon_bytes()
    if hashlib.sha256(data).hexdigest() != APP_ICON_SHA256:
        return None
    if folder is None:
        local = os.environ.get("LOCALAPPDATA")
        base = Path(local) if local else Path.home() / "AppData" / "Local"
        folder = base / "Livery Organizer for FH6" / "PreviewBridge"
    target = folder / f"livery-viewer-for-fh6-{APP_ICON_SHA256[:12]}.ico"
    try:
        if target.is_file() and hashlib.sha256(target.read_bytes()).hexdigest() == APP_ICON_SHA256:
            return target
        folder.mkdir(parents=True, exist_ok=True)
        scratch = target.with_name(target.name + f".{os.getpid()}.tmp")
        scratch.write_bytes(data)
        os.replace(scratch, target)
        return target
    except OSError:
        return None


def start_options(webview_start) -> dict:
    """webview.start に渡すアイコンの指定（icon を受け付けない版の pywebview や、書けないときは空）。"""
    import inspect
    try:
        accepts = "icon" in inspect.signature(webview_start).parameters
    except (TypeError, ValueError):
        accepts = False
    path = icon_path() if accepts else None
    return {"icon": str(path)} if path is not None else {}
